assert len(ROWS)==32
tasks=[]
for uid,title,deps,front,gates,figma,source,criteria in ROWS:
    tasks.append(dict(id=uid,title=title,implementationTasks=deps.split(','),frontendDependencies=front.split(',') if front else [],manualGates=gates.split(','),figma=figma,source=source,criteria=criteria.split('|'),issueNumber=issue_map.get(uid)))
assert all(t in backend_map for row in tasks for t in row['implementationTasks'])
ids={t['id'] for t in tasks}
assert all(f in ids for row in tasks for f in row['frontendDependencies'])
resolved=set()
while len(resolved)<len(ids):
    ready={t['id'] for t in tasks if set(t['frontendDependencies']) <= resolved}
    assert ready-resolved, 'Frontend prerequisite cycle'
    resolved |= ready
manual_map=json.loads((HERE/'manual-test-issue-map.json').read_text()) if (HERE/'manual-test-issue-map.json').exists() else {}

def link(uid):
    if uid.startswith('T'):
        return f'[{uid} — #{backend_map[uid]}](https://github.com/dacho-morgh/dacho/issues/{backend_map[uid]})'
    return f'[{uid} — #{issue_map[uid]}](https://github.com/dacho-morgh/dacho/issues/{issue_map[uid]})' if uid in issue_map else f'{uid} (see frontend delivery plan)'

for row in tasks:
    refs='\n'.join('- '+link(t) for t in row['implementationTasks'])
    earlier='\n'.join('- '+link(t) for t in row['frontendDependencies']) or '- Shared primitives can begin independently.'
    criteria='\n'.join('- [ ] '+c for c in row['criteria'])
    row['body']=f"""Frontend implementation work package **{row['id']}**: {row['title']}.

This refines the existing system backlog; the linked original tasks retain ownership of their backend/CMS or cross-layer contracts. Do not implement duplicate workflow rules in the browser. Product decisions through Q38 override conflicting Figma copy.

## Backend / original implementation links
{refs}

## Frontend sequence
{earlier}

## Design and current code
Figma file: https://www.figma.com/design/qVz7LsJUPwiXI3OMoW9kAj/Dashboard
Nodes/coverage: {row['figma']}.
Source entry points under `apps/frontend/src/components/dashboard/` unless a different path is stated: {row['source']}.
Source review is not a runtime pass. Missing screen families require design completion against the approved workflow.

## Deliverable and acceptance
{criteria}
- [ ] Integrate real authorized API responses, including loading/empty/denied/error and stale submission handling. No mocked completion evidence.
- [ ] Use Persian UI copy and existing shared components/style conventions. UI visibility supplements server authorization.

## Verification and handoff
Human gates: {', '.join(row['manualGates'])}. Run each gate when its slice is deployed; record build, tester, steps and evidence. Gates start **Not run**. Add focused automated coverage appropriate to the changed behavior and link defects. Reviewer forms, all qualitative/risk requiredness and the 2-point article cap are supplied in docs/system/review-rubric.md. Upload policy is Word/PDF, 10 MB per file, multiple representations on one field (docs/system/document-policy.json). Approved agreement text remains missing where applicable; unrequested aggregation and technical choices do not block unrelated work.

<!-- dacho-frontend-plan:{row['id']} -->
"""

(HERE/'frontend-tasks.json').write_text(json.dumps(tasks,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
text=['# Frontend delivery plan\n\nUpdated 2026-10-23. 32 frontend work packages refining the original 55 system tasks. This is a specification, not completed implementation. UI language remains Persian.\n',
'## Delivery order\n\n1. Agree shared DTOs/capabilities/errors and private file policy; ship FE01–FE07 and enable login/signup/profile human gates as slices become usable.\n2. Ship owner configuration and event intake (FE08–FE14), then assignments/reviews/chief decision (FE15–FE18).\n3. Ship financial package, investment memo, publication and scoped correspondence (FE19–FE23).\n4. Ship independent booth/attendance/receipt/cancellation flow (FE24–FE28).\n5. Apply FE29–FE30 throughout; finish real-backed FE31–FE32 and human full-journey gates.\n\nThe sequence is a dependency plan, not a promised calendar. Frontend shells/fixtures can proceed before endpoints, but real integration and a deployable test slice are required for acceptance.\n',
'## Traceability\n\n`Txx` denotes an original system issue. Some original issues already include frontend work; these FE packages split out the browser deliverable and must be coordinated rather than implemented twice. Backend dependencies are ordinary issue links, not an assertion that all linked issues are backend-only or GitHub-native blocking relationships.\n\n| Package | Frontend deliverable | Original task / backend contracts | Frontend prerequisites | Human gates |\n| --- | --- | --- | --- | --- |']
for t in tasks:
    label=link(t['id'])
    gates=', '.join(f'[{g}](https://github.com/dacho-morgh/dacho/issues/{manual_map[g]})' if g in manual_map else g for g in t['manualGates'])
    text.append(f"| {label} | {t['title']} | {', '.join(link(x) for x in t['implementationTasks'])} | {', '.join(link(x) for x in t['frontendDependencies']) or '—'} | {gates} |")
text.append('\n## Detailed work packages\n')
for t in tasks:
    text.extend([f"\n## {t['id']} — {t['title']}\n",t['body']])
(HERE/'frontend-plan.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
print(json.dumps({'frontendPackages':len(tasks),'mappedIssues':len(issue_map)}))
